// Stacked to Grouped Bars — Animation, route: jsx
// Source: stacked-to-grouped-bars
//
// Self-contained: every local import is inlined below. Requires only d3, motion, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useEffect, useMemo, useState } from 'react';
import * as d3 from 'd3';
import { motion } from 'motion/react';

// ---- inlined from stackedToGrouped ----
const seriesCount = 5;
const pointCount = 58;
const xIndices: number[] = Array.from({ length: pointCount }, (_, i) => i);

/** mulberry32: a fixed seed keeps the chart identical across reloads. */
function seededRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const random = seededRandom(20260813);

/** Five random gaussian bumps summed over a baseline, same shape as the notebook's `bumps`. */
function bumps(length: number): number[] {
  const values = new Array(length).fill(0).map(() => 0.1 + 0.1 * random());

  for (let j = 0; j < 5; ++j) {
    const x = 1 / (0.1 + random());
    const y = 2 * random() - 0.5;
    const z = 10 / (0.1 + random());
    for (let i = 0; i < length; ++i) {
      const w = (i / length - y) * z;
      values[i] += x * Math.exp(-w * w);
    }
  }

  return values.map((v) => Math.max(0, v));
}

/** `seriesCount` series of `pointCount` values, one bump curve each. */
const yz: number[][] = Array.from({ length: seriesCount }, () => bumps(pointCount));

const MARGIN = { top: 10, right: 10, bottom: 20, left: 10 };
const TOGGLE_MS = 2000;
const TRANSITION = { duration: 0.5, ease: 'easeInOut' } as const;

type Layout = 'stacked' | 'grouped';

type Bar = { id: string; series: number; index: number; y0: number; y1: number };

/** One row per series, each holding the same number of values, one per bar position. */
export type Data = number[][];

export default function StackedToGrouped({ data = yz, width }: { data?: Data; width: number }) {
  const height = Math.round(width * 0.54);
  const innerWidth = Math.max(0, width - MARGIN.left - MARGIN.right);
  const innerHeight = Math.max(0, height - MARGIN.top - MARGIN.bottom);

  const [layout, setLayout] = useState<Layout>('stacked');

  useEffect(() => {
    const id = window.setInterval(
      () => setLayout((current) => (current === 'stacked' ? 'grouped' : 'stacked')),
      TOGGLE_MS
    );
    return () => window.clearInterval(id);
  }, []);

  const x = useMemo(
    () =>
      d3
        .scaleBand<number>()
        .domain(d3.range(data[0].length))
        .range([0, innerWidth])
        .padding(0.08),
    [data, innerWidth]
  );

  const bars: Bar[] = useMemo(() => {
    const stack = d3.stack<number[], number>().keys(d3.range(data.length));
    return stack(d3.transpose(data)).flatMap((series, s) =>
      series.map(([y0, y1], index) => ({ id: `${s}-${index}`, series: s, index, y0, y1 }))
    );
  }, [data]);

  const yMax = useMemo(() => d3.max(data, (series) => d3.max(series) ?? 0) ?? 0, [data]);
  const y1Max = useMemo(() => d3.max(bars, (d) => d.y1) ?? 0, [bars]);

  const y = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain([0, layout === 'grouped' ? yMax : y1Max])
        .range([innerHeight, 0]),
    [layout, yMax, y1Max, innerHeight]
  );

  const color = useMemo(
    () => d3.scaleSequential(d3.interpolateBlues).domain([-0.5 * data.length, 1.5 * data.length]),
    [data]
  );

  if (width === 0) return null;

  const bandwidth = x.bandwidth();
  const groupWidth = bandwidth / data.length;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label={
        'Bar chart toggling every two seconds between a stacked and a grouped layout, ' +
        'each bar keeping its identity across the transition to preserve object constancy.'
      }
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        {bars.map((d) => {
          const value = d.y1 - d.y0;
          const stackedX = x(d.index) ?? 0;
          const groupedX = stackedX + groupWidth * d.series;
          const groupedY = y(value);
          return (
            <motion.rect
              key={d.id}
              fill={color(d.series)}
              animate={{
                x: layout === 'grouped' ? groupedX : stackedX,
                width: layout === 'grouped' ? groupWidth : bandwidth,
                y: layout === 'grouped' ? groupedY : y(d.y1),
                height: layout === 'grouped' ? innerHeight - groupedY : y(d.y0) - y(d.y1)
              }}
              transition={TRANSITION}
            />
          );
        })}
        <line
          x1={0}
          x2={innerWidth}
          y1={innerHeight}
          y2={innerHeight}
          stroke="var(--text)"
          strokeOpacity={0.2}
        />
      </g>
    </svg>
  );
}
